// Typed client and types for the Brew-Bruvs API, generated from the server's routes.
// Regenerate with `pnpm api:generate`; never edit src/generated by hand.
import createClient from "openapi-fetch";
import type { components, paths } from "./generated/schema.ts";

export type { components, paths };
export type ApiError = components["schemas"]["Error"];

export function createApiClient(baseUrl: string, init?: { fetch?: typeof fetch }) {
  return createClient<paths>({ baseUrl, ...init });
}
